import { Box } from "@/shared/ui/layout/Box";

interface OpStateAttrs { "data-op"?: string; "data-mark"?: string; "data-role"?: string }
interface NodeOp { op: string; node?: string; nodes?: string[]; edge?: [string, string]; at?: [string, string] }
interface GraphFrame {
  structure: "graph";
  nodes: { id: string; label?: string; x?: number; y?: number }[];
  edges: { from: string; to: string; weight?: number }[];
  ops?: NodeOp[];
  marks?: Record<string, string>;
  roles?: Record<string, string>;
}

function nodeOpStateAttrs(ops: readonly NodeOp[] | undefined, id: string): OpStateAttrs {
  const attrs: OpStateAttrs = {};
  for (const o of ops ?? []) {
    const hit = o.node === id || !!o.nodes?.includes(id) || !!o.edge?.includes(id) || !!o.at?.includes(id);
    if (hit) attrs["data-op"] = o.op;
  }
  return attrs;
}
function markStateAttrs(marks: Record<string, string> | undefined, key: string): OpStateAttrs {
  const mark = marks?.[key];
  return mark ? { "data-mark": mark } : {};
}
function roleStateAttrs(roles: Record<string, string> | undefined, key: string): OpStateAttrs {
  const role = roles?.[key];
  return role ? { "data-role": role } : {};
}

const GRAPH_VIEW = 320;
const RADIUS = 116;
function circularLayout(ids: readonly string[]): Record<string, { x: number; y: number }> {
  const cx = GRAPH_VIEW / 2;
  const cy = GRAPH_VIEW / 2;
  const n = Math.max(1, ids.length);
  const pos: Record<string, { x: number; y: number }> = {};
  ids.forEach((id, i) => {
    const t = (i / n) * 2 * Math.PI - Math.PI / 2;
    pos[id] = { x: cx + RADIUS * Math.cos(t), y: cy + RADIUS * Math.sin(t) };
  });
  return pos;
}
function layoutFor(nodes: readonly { id: string; x?: number; y?: number }[]): Record<string, { x: number; y: number }> {
  return circularLayout(nodes.map((n) => n.id));
}

const NODE_R = 19;
const edgeKey = (a: string, b: string) => [a, b].slice().sort().join("~");
export function GraphView({
  frame = {
    structure: "graph",
    nodes: [{ id: "a", label: "A" }, { id: "b", label: "B" }, { id: "c", label: "C" }, { id: "d", label: "D" }],
    edges: [{ from: "a", to: "b" }, { from: "b", to: "c" }, { from: "c", to: "d" }, { from: "d", to: "a" }],
    ops: [{ op: "visit", node: "b" }],
    marks: { a: "visited" },
    roles: { a: "start" },
  },
}: { frame?: GraphFrame }) {
  const { nodes, edges, ops, marks, roles } = frame;
  const pos = layoutFor(nodes);
  // The edges relaxed THIS frame (undirected) — stamped data-op="relax" so they flash.
  const relaxed = new Set(
    (ops ?? [])
      .filter((o): o is { op: "relax"; edge: [string, string] } => o.op === "relax")
      .map((o) => edgeKey(o.edge[0], o.edge[1])),
  );
  for (const o of ops ?? []) {
    if (o.op === "path") {
      const seq = (o as { nodes: string[] }).nodes;
      for (let i = 0; i < seq.length - 1; i++) relaxed.add(edgeKey(seq[i], seq[i + 1]));
    }
  }
  const nodeOps = (ops ?? []).filter((o) => o.op === "visit" || o.op === "frontier");

  return (
    <Box className="graph-view" role="img" aria-label="graph">
      <svg viewBox={`0 0 ${GRAPH_VIEW} ${GRAPH_VIEW}`} className="graph-svg" role="presentation">
        {edges.map((e) => {
          const a = pos[e.from];
          const b = pos[e.to];
          if (!a || !b) return null;
          const on = relaxed.has(edgeKey(e.from, e.to));
          const weighted = e.weight !== undefined && e.weight !== 1;
          return (
            <g key={`${e.from}-${e.to}`}>
              <line className="graph-edge" x1={a.x} y1={a.y} x2={b.x} y2={b.y} {...(on ? { "data-op": "relax" } : {})} />
              {weighted && (
                <text className="graph-weight" x={(a.x + b.x) / 2} y={(a.y + b.y) / 2} textAnchor="middle" dominantBaseline="central">
                  {e.weight}
                </text>
              )}
            </g>
          );
        })}
        {nodes.map((nd) => {
          const p = pos[nd.id];
          if (!p) return null;
          const attrs = {
            ...nodeOpStateAttrs(nodeOps, nd.id),
            ...markStateAttrs(marks, nd.id),
            ...roleStateAttrs(roles, nd.id),
          };
          return (
            <g key={nd.id} transform={`translate(${p.x} ${p.y})`}>
              <circle className="graph-node" r={NODE_R} {...attrs} />
              <text className="graph-node-label" textAnchor="middle" dominantBaseline="central">
                {nd.label ?? nd.id}
              </text>
            </g>
          );
        })}
      </svg>
    </Box>
  );
}
